package com.yjiyun.chatflows.manager;
import com.yjiyun.chatflows.manager.security.AuthService;
public final class ManagerAuthSelfTest { public static void main(String[] args){String regular="manager-regular-token-0123456789",admin="manager-admin-token-01234567890";AuthService auth=new AuthService(regular,admin);auth.requireRole("Bearer "+regular,"orchestrator","orchestrator","admin");auth.requireRole("Bearer "+admin,"admin","orchestrator","admin");boolean escalated=false;try{auth.requireRole("Bearer "+regular,"admin","orchestrator","admin");escalated=true;}catch(SecurityException expected){}if(escalated)throw new AssertionError("regular credential escalated via admin role");boolean same=false;try{new AuthService(regular,regular);same=true;}catch(IllegalArgumentException expected){}if(same)throw new AssertionError("identical regular/admin credentials accepted");System.out.println("[PASS] manager split regular/admin credentials prevent role-header escalation");} }
